const r = $input.first().json;
if (!r.ok) {
  // Klare Fehlermeldung statt leerer Tabelle
  throw new Error(r.hinweis || r.error || 'Links konnten nicht gelesen werden');
}
return [{ json: r }];

const quelle = $('Gesperrt?').first().json;
const vorhanden = $input.all().map((i) => i.json).filter((r) => r && r.url);

// Links, die sicher KEINE Stellen sind (eigene Seite, Messenger, Social Media ...)
const AUSSCHLUSS = ['missionfrei', 'wa.me', 'whatsapp.com', 'instagram.com', 'facebook.com', 'youtube.com', 'youtu.be', 'tiktok.com', 't.me/', 'calendly.com', 'paypal.', 'linktr.ee', 'googleadservices.', 'doubleclick.net', 'googlesyndication.'];

// Hinweis: Im n8n-Code-Knoten gibt es kein "new URL(...)".
// Deshalb zerlegen wir Adressen mit einem regulären Ausdruck selbst.
function zerlegeUrl(roh) {
  const m = String(roh || '').trim().match(/^(https?):\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/i);
  if (!m) return null;
  return { protokoll: m[1].toLowerCase(), host: m[2].toLowerCase(), pfad: m[3] || '/', query: m[4] || '' };
}

// Macht aus einer relativen Weiterleitung ("/karriere") eine volle Adresse.
function absoluteUrl(ziel, basis) {
  if (/^https?:\/\//i.test(ziel)) return ziel;
  const b = zerlegeUrl(basis);
  if (!b) return ziel;
  if (ziel.startsWith('//')) return b.protokoll + ':' + ziel;
  if (ziel.startsWith('/')) return b.protokoll + '://' + b.host + ziel;
  return b.protokoll + '://' + b.host + b.pfad.replace(/[^\/]*$/, '') + ziel;
}

// Zeigt eine Adresse nur noch auf eine allgemeine Karriere- oder Startseite?
function istAllgemeineSeite(ziel, original) {
  const z = zerlegeUrl(ziel);
  const o = zerlegeUrl(original);
  if (!z || !o) return false;
  const pfad = (u) => u.pfad.replace(/\/+$/, '').toLowerCase();
  const host = (u) => u.host.replace(/^www\./, '');
  if (host(z) === host(o) && pfad(z) === pfad(o)) return false; // z. B. nur http -> https
  const p = pfad(z);
  if (p === '') return true;
  if (/^(\/[a-z]{2}(-[a-z]{2})?)?(\/(karriere|career|careers|jobs|job|stellenangebote|stellen|offene-stellen|jobboerse|join-us|joinus|vacancies|work-with-us|search|suche))*$/.test(p)) return true;
  if (/[?&](error|expired|notfound|jobnotfound)=/i.test(z.query)) return true;
  return false;
}

// Vereinheitlichen, damit gleiche Links auch gleich aussehen:
// immer https, ohne #Anker, ohne Tracking-Parameter (utm_..., gclid ...), ohne "/" am Ende.
function normalisiere(roh) {
  const u = zerlegeUrl(roh);
  if (!u) return null;
  const params = u.query
    .replace(/^\?/, '')
    .split('&')
    .filter(Boolean)
    .filter((p) => !/^(utm_|gclid|fbclid|mc_|ref=|ref_|source=|trk|trackingid|_hs|hsa_)/i.test(p));
  let pfad = u.pfad || '/';
  if (pfad !== '/' && params.length === 0) pfad = pfad.replace(/\/+$/, '') || '/';
  return `https://${u.host}${pfad}${params.length ? '?' + params.join('&') : ''}`;
}

const gesehen = new Map();
for (const l of quelle.links || []) {
  const url = normalisiere(l.url);
  if (!url) continue;
  if (AUSSCHLUSS.some((a) => url.includes(a))) continue;
  if (!gesehen.has(url)) gesehen.set(url, l.text || '');
}

const bekannt = new Set(vorhanden.map((r) => r.url));
const jetzt = new Date().toISOString();
const neue_zeilen = [];
for (const [url, text] of gesehen) {
  if (bekannt.has(url)) continue;
  neue_zeilen.push({
    url,
    domain: zerlegeUrl(url).host.replace(/^www\./, ''),
    linktext: text,
    erstmals_gesehen: jetzt,
    nicht_mehr_gelistet: false,
    status: 'neu',
    freigabe: '',
  });
}

// Nur Zeilen anfassen, deren "gelistet"-Markierung sich ändert.
const markierungen = [];
for (const r of vorhanden) {
  if (String(r.linktext || '').startsWith('(manuell')) continue; // von dir hinzugefügt – nicht auf Missionfrei
  const gelistet = gesehen.has(r.url);
  if (Boolean(r.nicht_mehr_gelistet) === gelistet) markierungen.push({ id: r.id, nicht_mehr_gelistet: !gelistet });
}

return [
  {
    json: {
      quelle: quelle.ausDatei ? quelle.hinweis : 'live von der Seite gelesen',
      links_auf_der_seite: quelle.count,
      eindeutige_stellenlinks: gesehen.size,
      neu: neue_zeilen.length,
      schon_bekannt: gesehen.size - neue_zeilen.length,
      geaenderte_markierungen: markierungen.length,
      neue_zeilen,
      markierungen,
    },
  },
];
